/* The 2.7 linker's PowerPC disassembler (src/linker/PPCDisassembler.c's, for the -dis code dumps of
   DumpELFCodePPC.c): 2.6's, with the processors of CodeWarrior 9 (e500 and its SPE and cache instructions, isel,
   the 405's multiply-accumulate instructions, the 5xx/8xx/82xx PowerQUICCs, the context instructions), more special
   and device control registers with mnemonics of their own and operand helpers of their own (crN, gqrN, srN).

   Each primary opcode has a handler (data_004a7570, by data_004a19a6); opcodes 4, 19, 30, 31, 59 and 63 search or
   dispatch again on their extended opcodes. The data is the original's (0x004a194e-0x004a769c, generated by
   tools/gen_disdata.py: PPCDis27, with a macro data_XXXXXXXX for each object at its address), so its tables keep
   their layout (the searches read past their ends, as the original's). */
#include "linker/PPCDisassembler.h"

extern int sprintf(char *s, const char *format, ...);
extern char *strcpy(char *dest, const char *source);
extern char *strcat(char *dest, const char *source);
extern unsigned char __ctype_map[];   /* MSL's: & 0xdc, a printable character */

/* A primary opcode's handler (data_004a7570): UNUSED 0, INSN the instruction, PC its address (instruction + base),
   MNEMONIC the mnemonic's buffer (dis_mnemonic too). */
typedef void (*DisHandler)(long unused, unsigned long insn, long pc, char *mnemonic);

/* An extended opcode's handler, in the tables the dispatchers search (6 bytes: the opcode, the handler's index in
   data_004a7570). */
#pragma options align = packed
typedef struct DisExtended {
    unsigned long xo;
    unsigned char handler;
    unsigned char pad;
} DisExtended;
#pragma options align = reset

/* An instruction's entry in the tables the handlers search (16 bytes): its extended opcode, its operands' form, its
   name, the processors it is valid on (none of dis_processors: invalid) and its flags (0x40000000: valid only with
   options 0x40000000; & 6, or & 0xe for opcode 19, added to dis_flags). */
typedef struct DisOpcode {
    unsigned short xo;
    unsigned short form;
    char *name;
    unsigned long processors;
    unsigned long flags;
} DisOpcode;

static void PPCDis_Branch(long unused, unsigned long insn, long pc, char *mnemonic);
static void PPCDis_BranchConditional(long unused, unsigned long insn, long pc, char *mnemonic);
static void PPCDis_SystemCall(long unused, unsigned long insn, long pc, char *mnemonic);
static void PPCDis_DForm(long unused, unsigned long insn, long pc, char *mnemonic);
static void PPCDis_LoadDoubleword(long unused, unsigned long insn, long pc, char *mnemonic);
static void PPCDis_XForm(long unused, unsigned long insn, long pc, char *mnemonic);
static void PPCDis_XFormE(long unused, unsigned long insn, long pc, char *mnemonic);
static void PPCDis_Isel(long unused, unsigned long insn, long pc, char *mnemonic);
static void PPCDis_Opcode19(long unused, unsigned long insn, long pc, char *mnemonic);
static void PPCDis_MoveSpecialRegister(long unused, unsigned long insn, long pc, char *mnemonic);
static void PPCDis_Mtfsf(long unused, unsigned long insn, long pc, char *mnemonic);
static void PPCDis_Sradi(long unused, unsigned long insn, long pc, char *mnemonic);
static void PPCDis_IntegerArithmetic(long unused, unsigned long insn, long pc, char *mnemonic);
static void PPCDis_FloatAForm(long unused, unsigned long insn, long pc, char *mnemonic);
static void PPCDis_Rotate(long unused, unsigned long insn, long pc, char *mnemonic);
static void PPCDis_RotateMD(long unused, unsigned long insn, long pc, char *mnemonic);
static void PPCDis_RotateMDS(long unused, unsigned long insn, long pc, char *mnemonic);
static void PPCDis_Opcode30(long unused, unsigned long insn, long pc, char *mnemonic);
static void PPCDis_Opcode31(long unused, unsigned long insn, long pc, char *mnemonic);
static void PPCDis_Opcode63(long unused, unsigned long insn, long pc, char *mnemonic);
static void PPCDis_Opcode4(long unused, unsigned long insn, long pc, char *mnemonic);
static void PPCDis_PairedSingle(long unused, unsigned long insn, long pc, char *mnemonic);
static void PPCDis_Context(long unused, unsigned long insn, long pc, char *mnemonic);
static void PPCDis_Invalid(long unused, unsigned long insn, long pc, char *mnemonic);

