#define C_COUNT(table) (sizeof(table) / sizeof((table)[0]))

/* With extended mnemonics, the mnemonic of register NUMBER in TABLE (COUNT entries) valid for dis_processors, and
   general register REG as its operand when it has one; 0 when there is none. */
static int C_NamedRegister(C_Register *table, unsigned long count, long number, unsigned long reg, char *mnemonic) {
    unsigned long i;
    int t;
    unsigned long bits;

    if (!dis_extended)
        return 0;
    for (i = 0; i < count; i++) {
        if (table[i].number != number)
            continue;
        for (t = 0; t < 2; t++) {
            if (!table[i].tests[t].mask)
                continue;
            bits = dis_processors & table[i].tests[t].mask;
            if (table[i].tests[t].nonzero ? !bits : bits != 0)
                break;
        }
        if (t < 2)
            continue;
        Dis_Mnemonic(mnemonic, table[i].name, 0);
        if (table[i].operand)
            Dis_AddOperand(Dis_Register(reg));
        return 1;
    }
    return 0;
}

/* The moves to and from the condition, special, time base and device control registers (opcode 31: mtcrf,
   mfspr/mtspr with their extended mnemonics, mftb, mfdcr/mtdcr with the 403/405's) (0x0047ebc0). */
static void PPCDis_MoveSpecialRegister(long unused, unsigned long insn, long pc, char *mnemonic) {
    unsigned long reg = insn >> 21 & 0x1f;
    unsigned long field = insn >> 11 & 0x3ff;
    long number = (long)((field >> 5) + (field & 0x1f) * 32);
    char text[32];
    char *name;

    switch (insn >> 1 & 0x3ff) {
    case 0x90:
        Dis_Mnemonic(mnemonic, data_004a65f8, 0);   /* "mtcrf" */
        sprintf(text, data_004a6600, insn >> 12 & 0xff);   /* "0x%x" */
        Dis_AddOperand(text);
        Dis_AddOperand(Dis_Register(reg));
        break;
    case 0x143:
        if (C_NamedRegister(C_mfdcr, C_COUNT(C_mfdcr), number, reg, mnemonic))
            return;
        Dis_Mnemonic(mnemonic, data_004a67d8, 0);   /* "mfdcr" */
        Dis_AddOperand(Dis_Register(reg));
        Dis_AddOperand(Dis_DeviceControlRegister(number));
        break;
    case 0x153:
        if (C_NamedRegister(C_mfspr, C_COUNT(C_mfspr), number, reg, mnemonic))
            return;
        Dis_Mnemonic(mnemonic, data_004a6450, 0);   /* "mfspr" */
        Dis_AddOperand(Dis_Register(reg));
        Dis_AddOperand(Dis_SpecialRegister(number));
        break;
    case 0x173:
        /* mftb: 268 mftb, 269 mftbu; else by the field as encoded (not swapped) */
        if (number == 0x10c)
            name = data_004a6608;   /* "mftb" */
        else if (number == 0x10d)
            name = data_004a6610;   /* "mftbu" */
        else if (field == 0x188)
            name = data_004a6618;   /* "mtbr" */
        else
            name = data_004a6620;   /* "mtbru" */
        Dis_Mnemonic(mnemonic, name, 0);
        Dis_AddOperand(Dis_Register(reg));
        break;
    case 0x1c3:
        if (C_NamedRegister(C_mtdcr, C_COUNT(C_mtdcr), number, reg, mnemonic))
            return;
        Dis_Mnemonic(mnemonic, data_004a6990, 0);   /* "mtdcr" */
        Dis_AddOperand(Dis_DeviceControlRegister(number));
        Dis_AddOperand(Dis_Register(reg));
        break;
    case 0x1d3:
        if (C_NamedRegister(C_mtspr, C_COUNT(C_mtspr), number, reg, mnemonic))
            return;
        Dis_Mnemonic(mnemonic, data_004a65f0, 0);   /* "mtspr" */
        Dis_AddOperand(Dis_SpecialRegister(number));
        Dis_AddOperand(Dis_Register(reg));
        break;
    default:
        dis_flags = 0;
        break;
    }
}

/* Opcode 63 mtfsf: FM,frB (0x004816d0). */
static void PPCDis_Mtfsf(long unused, unsigned long insn, long pc, char *mnemonic) {
    Dis_Mnemonic(mnemonic, (insn & 1) ? data_004a6998 : data_004a69a0, 0);   /* "mtfsf." : "mtfsf" */
    Dis_AddOperand(Dis_Decimal((long)(insn >> 17 & 0xff)));
    Dis_AddOperand(Dis_FloatRegister(insn >> 11 & 0x1f));
}

/* Opcode 31 sradi (XS-form): rA,rS,SH (6 bits) (0x00481730). */
static void PPCDis_Sradi(long unused, unsigned long insn, long pc, char *mnemonic) {
    Dis_Mnemonic(mnemonic, (insn & 1) ? data_004a69a8 : data_004a69b0, 0);   /* "sradi." : "sradi" */
    Dis_AddOperand(Dis_Register(insn >> 16 & 0x1f));
    Dis_AddOperand(Dis_Register(insn >> 21 & 0x1f));
    Dis_AddOperand(Dis_Decimal((long)((insn >> 1 & 1) << 5 | (insn >> 11 & 0x1f))));
}

/* Opcode 31's XO-form arithmetic (add, subf, mullw, divw, neg, ...; data_004a6a78 by bits 1-9): "o" for OE, "."
   for Rc. Forms: 1, 2 rD,rA,rB; 3 rD,rA (0x004817c0). */
static void PPCDis_IntegerArithmetic(long unused, unsigned long insn, long pc, char *mnemonic) {
    DisOpcode *entry = Dis_Find(insn >> 1 & 0x1ff, (DisOpcode *)data_004a6a78, 0x1b);
    char buf[12];
    char *name;

    if (!Dis_Valid(entry, 6))
        return;
    name = entry->name;
    if (insn >> 10 & 1) {
        strcpy(buf, name);
        strcat(buf, data_004a6014);   /* "o" */
        name = buf;
    }
    Dis_Mnemonic(mnemonic, name, (int)(insn & 1));
    switch (entry->form) {
    case 1:
    case 2:
        Dis_AddOperand(Dis_Register(insn >> 21 & 0x1f));
        Dis_AddOperand(Dis_Register(insn >> 16 & 0x1f));
        Dis_AddOperand(Dis_Register(insn >> 11 & 0x1f));
        break;
    case 3:
        Dis_AddOperand(Dis_Register(insn >> 21 & 0x1f));
        Dis_AddOperand(Dis_Register(insn >> 16 & 0x1f));
        break;
    }
}

/* The A-form floating point instructions (opcodes 59 and 63, data_004a6c88 and data_004a6d80 by bits 1-5: fadd,
   fsub, fmul, fdiv, fsqrt, fres, frsqrte, fsel, fmadd, fmsub, fnmadd, fnmsub and their single forms), "." for Rc.
   Forms: 1, 5 frD,frA,frB; 2 frD,frA,frC,frB; 3 frD,frA,frC; 4 frD,frB (0x00481a00). */
static void PPCDis_FloatAForm(long unused, unsigned long insn, long pc, char *mnemonic) {
    DisOpcode *entry;
    unsigned long d = insn >> 21 & 0x1f;
    unsigned long a = insn >> 16 & 0x1f;
    unsigned long b = insn >> 11 & 0x1f;
    unsigned long c = insn >> 6 & 0x1f;

    if ((insn >> 26) == 59)
        entry = Dis_Find(insn >> 1 & 0x1f, (DisOpcode *)data_004a6c88, 10);
    else
        entry = Dis_Find(insn >> 1 & 0x1f, (DisOpcode *)data_004a6d80, 0xb);
    if (!Dis_Valid(entry, 6))
        return;
    Dis_Mnemonic(mnemonic, entry->name, (int)(insn & 1));
    switch (entry->form) {
    case 1:
    case 5:
        Dis_AddOperand(Dis_FloatRegister(d));
        Dis_AddOperand(Dis_FloatRegister(a));
        Dis_AddOperand(Dis_FloatRegister(b));
        break;
    case 2:
        Dis_AddOperand(Dis_FloatRegister(d));
        Dis_AddOperand(Dis_FloatRegister(a));
        Dis_AddOperand(Dis_FloatRegister(c));
        Dis_AddOperand(Dis_FloatRegister(b));
        break;
    case 3:
        Dis_AddOperand(Dis_FloatRegister(d));
        Dis_AddOperand(Dis_FloatRegister(a));
        Dis_AddOperand(Dis_FloatRegister(c));
        break;
    case 4:
        Dis_AddOperand(Dis_FloatRegister(d));
        Dis_AddOperand(Dis_FloatRegister(b));
        break;
    }
}

/* "NAME ra,rs" followed by the immediates N and B (COUNT 2) or N alone (COUNT 1). */
static void Dis_Rotated(unsigned long insn, char *mnemonic, char *name, unsigned long ra, unsigned long rs, int count,
                        long n, long b) {
    Dis_Mnemonic(mnemonic, name, (int)(insn & 1));
    Dis_AddOperand(Dis_Register(ra));
    Dis_AddOperand(Dis_Register(rs));
    Dis_AddOperand(Dis_Decimal(n));
    if (count > 1)
        Dis_AddOperand(Dis_Decimal(b));
}

/* Primary opcodes 20-23: rlwimi, rlwinm, rlmi (options 2), rlwnm (data_004a6e50), and with extended mnemonics
   insrwi, inslwi, clrrwi, clrlwi, rotlwi, rotrwi, slwi, srwi, extlwi, extrwi, clrlslwi and rotlw (0x00481ba0). */
static void PPCDis_Rotate(long unused, unsigned long insn, long pc, char *mnemonic) {
    unsigned long rs = insn >> 21 & 0x1f;
    unsigned long ra = insn >> 16 & 0x1f;
    unsigned long sh = insn >> 11 & 0x1f;   /* rb for rlwnm */
    unsigned long mb = insn >> 6 & 0x1f;
    unsigned long me = insn >> 1 & 0x1f;
    unsigned long opcode = insn >> 26;

    if (dis_extended) {
        switch (opcode) {
        case 20:
            /* insrwi ra,rs,n,b: n = me + 1 - mb, b = mb */
            if (sh == 31 - me) {
                Dis_Rotated(insn, mnemonic, data_004a6e60, ra, rs, 2, (long)(me + 1 - mb), (long)mb);
                return;
            }
            /* inslwi ra,rs,n,b */
            if (sh == 32 - mb) {
                Dis_Rotated(insn, mnemonic, data_004a6e68, ra, rs, 2, (long)(me + 1 - mb), (long)mb);
                return;
            }
            break;
        case 21:
            if (sh == 0) {
                if (mb == 0) {
                    Dis_Rotated(insn, mnemonic, data_004a6e70, ra, rs, 1, (long)(31 - me), 0);   /* clrrwi */
                    return;
                }
                if (me == 31) {
                    Dis_Rotated(insn, mnemonic, data_004a6e78, ra, rs, 1, (long)mb, 0);          /* clrlwi */
                    return;
                }
            }
            if (mb == 0 && me == 31) {
                /* rotlwi up to 17, else rotrwi (with SH itself, not 32 - SH) */
                Dis_Rotated(insn, mnemonic, sh <= 17 ? data_004a6e80 : data_004a6e88, ra, rs, 1, (long)sh, 0);
                return;
            }
            if (mb == 0 && sh == 31 - me) {
                Dis_Rotated(insn, mnemonic, data_004a6e90, ra, rs, 1, (long)sh, 0);              /* slwi */
                return;
            }
            if (me == 31 && mb == 32 - sh) {
                Dis_Rotated(insn, mnemonic, data_004a6e98, ra, rs, 1, (long)(32 - sh), 0);       /* srwi */
                return;
            }
            if (mb == 0 && sh != 0) {
                Dis_Rotated(insn, mnemonic, data_004a6ea0, ra, rs, 2, (long)(me + 1), (long)sh); /* extlwi */
                return;
            }
            if (me == 31) {
                /* extrwi ra,rs,n,b: n = 32 - mb, b = sh - n (the original's test n == sh - (sh - n) always
                   holds) */
                Dis_Rotated(insn, mnemonic, data_004a6ea8, ra, rs, 2, (long)(32 - mb), (long)(sh - (32 - mb)));
                return;
            }
            /* clrlslwi ra,rs,b,n: b = sh + mb, n = sh */
            if (sh == 31 - me && sh + mb < 32) {
                Dis_Rotated(insn, mnemonic, data_004a6eb0, ra, rs, 2, (long)(sh + mb), (long)sh);
                return;
            }
            break;
        case 23:
            if (mb == 0 && me == 31) {
                Dis_Mnemonic(mnemonic, data_004a6ebc, (int)(insn & 1));                         /* rotlw */
                Dis_AddOperand(Dis_Register(ra));
                Dis_AddOperand(Dis_Register(rs));
                Dis_AddOperand(Dis_Register(sh));
                return;
            }
            break;
        }
    }

    Dis_Mnemonic(mnemonic, DIS_NAMES(data_004a6e50)[opcode - 20], (int)(insn & 1));
    Dis_AddOperand(Dis_Register(ra));
    Dis_AddOperand(Dis_Register(rs));
    switch (opcode) {
    case 20:
    case 21:
        Dis_AddOperand(Dis_Decimal((long)sh));
        break;
    case 22:
        if (!(dis_options & 2)) {
            dis_flags = 0;
            return;
        }
        /* fall through */
    case 23:
        Dis_AddOperand(Dis_Register(sh));
        break;
    }
    Dis_AddOperand(Dis_Decimal((long)mb));
    Dis_AddOperand(Dis_Decimal((long)me));
}

/* Opcode 30 MD-form: rldicl, rldicr, rldic, rldimi (bits 2-4 < 4) rA,rS,SH,MB (6 bits each) (0x004821f0). */
static void PPCDis_RotateMD(long unused, unsigned long insn, long pc, char *mnemonic) {
    unsigned long xo = insn >> 2 & 7;

    if (xo > 3) {
        dis_flags = 0;
        return;
    }
    Dis_Mnemonic(mnemonic, DIS_NAMES(data_004a6ee4)[xo], (int)(insn & 1));
    Dis_AddOperand(Dis_Register(insn >> 16 & 0x1f));
    Dis_AddOperand(Dis_Register(insn >> 21 & 0x1f));
    Dis_AddOperand(Dis_Decimal((long)((insn >> 1 & 1) << 5 | (insn >> 11 & 0x1f))));
    Dis_AddOperand(Dis_Decimal((long)((insn >> 5 & 1) << 5 | (insn >> 6 & 0x1f))));
}

/* Opcode 30 MDS-form: rldcl, rldcr (bits 1-4 8, 9) rA,rS,rB,MB (0x004822c0). */
static void PPCDis_RotateMDS(long unused, unsigned long insn, long pc, char *mnemonic) {
    long xo = (long)(insn >> 1 & 0xf) - 8;

    if (xo != 0 && xo != 1) {
        dis_flags = 0;
        return;
    }
    Dis_Mnemonic(mnemonic, DIS_NAMES(data_004a6f04)[xo], (int)(insn & 1));
    Dis_AddOperand(Dis_Register(insn >> 16 & 0x1f));
    Dis_AddOperand(Dis_Register(insn >> 21 & 0x1f));
    Dis_AddOperand(Dis_Register(insn >> 11 & 0x1f));
    Dis_AddOperand(Dis_Decimal((long)((insn >> 5 & 1) << 5 | (insn >> 6 & 0x1f))));
}

/* Opcode 30: MD-form (bits 1-4 < 8) or MDS-form (0x00482380). */
static void PPCDis_Opcode30(long unused, unsigned long insn, long pc, char *mnemonic) {
    if ((insn >> 1 & 0xf) < 8)
        PPCDis_RotateMD(unused, insn, pc, mnemonic);
    else
        PPCDis_RotateMDS(unused, insn, pc, mnemonic);
}

/* Opcode 31: isel (xo & 0x1f == 0xf, not 0x6f) by itself, the e500's bblels and bblelr, the rest by bits 1-10
   (data_004a6f0c) (0x00482420). */
static void PPCDis_Opcode31(long unused, unsigned long insn, long pc, char *mnemonic) {
    unsigned long xo = (unsigned short)insn >> 1;

    if ((xo & 0x1f) == 0xf && (xo & 0x7f) != 0x6f)
        PPCDis_Isel(unused, insn, pc, mnemonic);
    else if (insn == 0x7c000818 && (dis_processors & 0x40000))
        Dis_Mnemonic(mnemonic, data_004a743a, 0);   /* "bblels" */
    else if (insn == 0x7c000898 && (dis_processors & 0x40000))
        Dis_Mnemonic(mnemonic, data_004a7442, 0);   /* "bblelr" */
    else
        Dis_Call(unused, Dis_FindHandler(xo & 0x3ff, (DisExtended *)data_004a6f0c, 0xdd), insn, pc, mnemonic);
}

/* Opcodes 59 and 63 (floating point): A-form by bits 1-5 (data_004a744a) when bit 5 is set, else X-form by bits
   1-10 (data_004a748c) (0x004824f0). */
static void PPCDis_Opcode63(long unused, unsigned long insn, long pc, char *mnemonic) {
    unsigned char handler;

    if (!(insn >> 1 & 0x10))
        handler = Dis_FindHandler(insn >> 1 & 0x3ff, (DisExtended *)data_004a748c, 0x12);
    else
        handler = Dis_FindHandler(insn >> 1 & 0x1f, (DisExtended *)data_004a744a, 0xb);
    Dis_Call(unused, handler, insn, pc, mnemonic);
}

/* Opcodes 56, 57, 60, 61 (data_004a7508): psq_l, psq_lu, psq_st, psq_stu frD,d(rA),W,gqrI (d unsigned, 12 bits), or
   frD,address from r0 (0x00482560). */
static void PPCDis_PairedSingle(long unused, unsigned long insn, long pc, char *mnemonic) {
    unsigned long ra = insn >> 16 & 0x1f;
    int i;

    for (i = 0; i < 4; i++) {
        if ((insn >> 26 & 0x3f) == ((unsigned long *)data_004a7508)[i])
            break;
    }
    Dis_Mnemonic(mnemonic, DIS_NAMES(data_004a74f8)[i], 0);
    Dis_AddOperand(Dis_FloatRegister(insn >> 21 & 0x1f));
    if (ra == 0)
        Dis_AddOperand(Dis_Absolute((long)(insn & 0xfff)));
    else
        Dis_AddOperand(Dis_Displacement((short)(insn & 0xfff), ra));
    Dis_AddOperand(Dis_Decimal((long)(insn >> 15 & 1)));
    Dis_AddOperand(Dis_QuantizationRegister((long)(insn >> 12 & 7)));
}

/* Opcode 0 (processor 0x40000): restucontext, copyucontext, swapucontext, swapccontext, and loadcontext,
   savecontext d(rA) (0x00482630). */
static void PPCDis_Context(long unused, unsigned long insn, long pc, char *mnemonic) {
    short low = (short)insn;

    if (!(dis_processors & 0x40000)) {
        dis_flags = 0;
        return;
    }
    switch (low) {
    case 4:
        Dis_Mnemonic(mnemonic, data_004a7518, 0);   /* "restucontext" */
        break;
    case 8:
        Dis_Mnemonic(mnemonic, data_004a7528, 0);   /* "copyucontext" */
        break;
    case 0xc:
        Dis_Mnemonic(mnemonic, data_004a7538, 0);   /* "swapucontext" */
        break;
    case 0xe:
        Dis_Mnemonic(mnemonic, data_004a7548, 0);   /* "swapccontext" */
        break;
    default:
        switch (insn & 7) {
        case 1:
            Dis_Mnemonic(mnemonic, data_004a7558, 0);   /* "loadcontext" */
            break;
        case 3:
            Dis_Mnemonic(mnemonic, data_004a7564, 0);   /* "savecontext" */
            break;
        default:
            dis_flags = 0;
            return;
        }
        Dis_AddOperand(Dis_Displacement((short)((low >> 3) * 8), insn >> 16 & 0x1f));
        break;
    }
}

/* Not an instruction (0x00482730). */
static void PPCDis_Invalid(long unused, unsigned long insn, long pc, char *mnemonic) {
    dis_flags = 0;
}

/* Disassembles the instruction at INSTRUCTION (its address INSTRUCTION + BASE, PC for the callback) into MNEMONIC,
   OPERANDS and COMMENT, with OPTIONS (the processors in its low 28 bits, see dis_options) and PROC for the
   operands' names. *STATE is set to 4 (the instruction's length). Returns dis_flags (0: not an instruction, shown as
   dc.l with its bytes) (0x004828d0). */
unsigned short PPCDis_Disassemble(unsigned char *instruction, long base, unsigned long options, char *mnemonic,
                                  char *operands, char *comment, long pc, long *state, DisassemblerOperandProc proc) {
    unsigned long insn;
    long value;
    char text[4];
    int i;

    dis_processors = options & 0xfffffff;
    if (!dis_processors)
        dis_processors = 0xff6fffd;
    if (options & 0x4000000)
        dis_hexPrefix = data_004a75d0;   /* "0x" */
    else
        dis_hexPrefix = data_004a75d4;   /* "$" */
    if (!dis_started) {
        *(short *)data_004a1950 = 0;
        dis_started = 1;
    }
    *state = 4;
    dis_flags = 1;
    dis_extended = (options & 0x8000000) == 0;
    *comment = 0;
    *operands = *comment;
    *mnemonic = *operands;
    dis_operandLength = 0;
    dis_mnemonic = mnemonic;
    dis_operands = operands;
    dis_comment = comment;
    dis_proc = proc;
    dis_pc = pc;
    dis_instruction = instruction;
    dis_base = base;
    dis_options = options;
    if (options & 0x80000000)
        insn = (unsigned long)instruction[3] << 24 | (unsigned long)instruction[2] << 16 |
               (unsigned long)instruction[1] << 8 | instruction[0];
    else
        insn = (unsigned long)instruction[0] << 24 | (unsigned long)instruction[1] << 16 |
               (unsigned long)instruction[2] << 8 | instruction[3];
    Dis_Call(0, (unsigned char)data_004a19a6[insn >> 26], insn, (long)(instruction + base), mnemonic);
    if (!dis_flags) {
        strcpy(mnemonic, data_004a75d8);   /* "dc.l" */
        sprintf(operands, data_004a75e0, insn);   /* "0x%08x" */
        value = insn;
        for (i = 0; i < 4; i++) {
            if (DIS_PRINTABLE(value & 0xff))
                text[i] = (char)value;
            else
                text[i] = '.';
            value >>= 8;
        }
        if (dis_options & 0x80000000)
            sprintf(comment, data_004a75e8, text[0], text[1], text[2], text[3]);   /* "; Invalid opcode '%c%c%c%c'" */
        else
            sprintf(comment, data_004a75e8, text[3], text[2], text[1], text[0]);
    }
    return dis_flags;
}
